const { performance } = require('node:perf_hooks');
const { getDB } = require('./src/db');
const { getSemanticKnowledge } = require('./src/semantic');
const { getProfileManager } = require('./src/profile');
const { getGitBackupManager } = require('./src/git_backup');

console.log('--- BẮT ĐẦU BENCHMARK THỰC TẾ ---');

// 1. Benchmark Profile Read (Tier 0)
let t0 = performance.now();
const profile = getProfileManager();
const facts = profile.getAll();
let tProfile = (performance.now() - t0).toFixed(2);

// 2. Benchmark Hybrid Search (BM25 + 128-dim Dense Vector)
t0 = performance.now();
const semantic = getSemanticKnowledge();
const results = semantic.searchKnowledge('kiến trúc hệ thống git second brain', { limit: 5 });
let tSearch = (performance.now() - t0).toFixed(2);

// 3. Benchmark SQLite WAL Read
t0 = performance.now();
const db = getDB();
const cnt = db.get('SELECT COUNT(*) as count FROM episodes').count;
let tDb = (performance.now() - t0).toFixed(2);

// 4. Benchmark Snapshot Export
t0 = performance.now();
const gitMgr = getGitBackupManager();
const exp = gitMgr.exportDataSnapshot();
let tExport = (performance.now() - t0).toFixed(2);

console.log(`1. Đọc toàn bộ Hồ sơ (Profile)                         : ${tProfile} ms (${facts.length} mục)`);
console.log(`2. True Hybrid Search (BM25 + Dense Vector 128-dim)    : ${tSearch} ms (${results.length} kết quả)`);
console.log(`3. Đọc dữ liệu từ SQLite WAL                           : ${tDb} ms (${cnt} sự kiện)`);
console.log(`4. Xuất 6 tệp Text Snapshot & SQL Dump trọn vẹn        : ${tExport} ms (${exp.exportedFiles.length} tệp)`);
'@

